package org.marketreview.nativeapp;
import java.util.*;
/** Pure, causal VWAP data contract; no Engine/Android/network dependency. */
public final class Vwap {
 private Vwap(){}
 public static final class Point {public long time=-1;public String session="";public double high=Double.NaN,low=Double.NaN,close=Double.NaN,volume=Double.NaN,amount=Double.NaN;public boolean valid=true,closed=true,axisGap=false;}
 public static final class Params {public String mode="legacy-close-approx",anchor="session",period="intraday",anchorId="",quantities="incremental",volumeUnit="unknown",priceBasis="unknown";public double volumeToShares=Double.NaN,amountToCny=Double.NaN;public boolean coversFromOpen=false;}
 public static final class Series {public final double[] values;public final String[] reasons;public final boolean[] provisional,breakBefore;public String label,explanation,coverage;public boolean approximate;Series(int n){values=new double[n];Arrays.fill(values,Double.NaN);reasons=new String[n];Arrays.fill(reasons,"unavailable");provisional=new boolean[n];breakBefore=new boolean[n];Arrays.fill(breakBefore,true);}}
 static void require(boolean b,String why){if(!b)throw new IllegalArgumentException(why);}
 static boolean date(String s){if(s==null||!s.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"))return false;try{return java.time.LocalDate.parse(s).getYear()>0;}catch(Exception e){return false;}}
 public static Series calculate(List<Point> input,Params p){boolean actual=p.mode.equals("actual-amount"),session=p.anchor.equals("session"),cumulative=p.quantities.equals("cumulative");require(actual||p.mode.equals("legacy-close-approx")||p.mode.equals("hlc3-approx"),"unsupported VWAP mode");require(session||p.anchor.equals("loaded-window"),"unsupported VWAP anchor");require(Arrays.asList("intraday","day","week","month","year").contains(p.period),"unsupported period");require(!session||p.period.equals("intraday")||p.period.equals("day"),"aggregated multi-day bars cannot be session VWAP");require(session||!p.anchorId.isEmpty(),"loaded window requires explicit actual anchor ID");require(p.quantities.equals("incremental")||cumulative,"quantity semantics must be declared");require(!cumulative||(actual&&session),"cumulative quantities only support actual session ratio; do not double-sum");Series out=new Series(input.size());out.approximate=!actual;out.label=actual?"真实成交金额/成交量均价":p.mode.equals("hlc3-approx")?"HLC3×量近似VWAP":"旧收盘价×量近似VWAP";out.label+=session?" · 按交易日":" · 明确加载窗口 "+p.anchorId;out.explanation=actual?"需匹配金额/成交量期间、明确CNY及股数换算、未复权价格；无金额或单位不明不回退。":"价格×成交量权重估计，不是真实成交均价；旧代码默认close而非HLC3。";out.explanation+=" 缺失观察不补0；区间缺数后不跳过误算。仅使用当前及此前输入。";out.explanation+=" 原量单位："+p.volumeUnit+"；数量口径："+p.quantities+"；价格口径："+p.priceBasis+"。";if(actual)out.explanation+=" 原量×"+(Double.isFinite(p.volumeToShares)?Double.toString(p.volumeToShares):"未知")+"=股，原金额×"+(Double.isFinite(p.amountToCny)?Double.toString(p.amountToCny):"未知")+"=CNY（均由来源合同声明）。";out.coverage=p.coversFromOpen?"来源声明从开盘覆盖；完整性仍以源记录为准":"从当前提供范围计算，不声称全日完整覆盖";boolean knownUnit=!p.volumeUnit.isEmpty()&&!p.volumeUnit.equals("unknown")&&!p.volumeUnit.equals("未知"),unit=knownUnit&&(!actual||(Double.isFinite(p.volumeToShares)&&p.volumeToShares>0&&Double.isFinite(p.amountToCny)&&p.amountToCny>0));double sumV=0,sumA=0,lastV=-1,lastA=-1;boolean tainted=false;String day="";long previous=-1;
 for(int i=0;i<input.size();i++){Point x=input.get(i);boolean newDay=session&&date(x.session)&&!x.session.equals(day);if(newDay){day=x.session;sumV=sumA=0;lastV=lastA=-1;tainted=false;}out.breakBefore[i]=i==0||(session&&p.period.equals("intraday")&&newDay)||!Double.isFinite(out.values[i-1]);out.provisional[i]=!x.closed&&!x.axisGap;if(x.time<0||x.time<=previous){out.reasons[i]="missing-or-unordered-time";if(!cumulative)tainted=true;continue;}previous=x.time;if(x.axisGap){out.reasons[i]="axis-gap-not-observation";continue;}if(session&&!date(x.session)){out.reasons[i]="missing-session-date";if(!cumulative)tainted=true;continue;}if(!unit){out.reasons[i]="quantity-unit-unknown";if(!cumulative)tainted=true;continue;}if(actual&&!p.priceBasis.equals("unadjusted")){out.reasons[i]="actual-price-basis-not-unadjusted";if(!cumulative)tainted=true;continue;}if(!x.valid){out.reasons[i]="invalid-observation";if(!cumulative)tainted=true;continue;}if(!Double.isFinite(x.volume)||x.volume<0){out.reasons[i]="missing-or-negative-volume";if(!cumulative)tainted=true;continue;}if(actual&&(!Double.isFinite(x.amount)||x.amount<0)){out.reasons[i]="missing-or-negative-amount";if(!cumulative)tainted=true;continue;}if(tainted){out.reasons[i]=cumulative?"earlier-cumulative-reset":"earlier-observation-gap";continue;}double volume=x.volume*(actual?p.volumeToShares:1),amount=0;if(!Double.isFinite(volume)){out.reasons[i]="quantity-overflow";if(!cumulative)tainted=true;continue;}if(actual){amount=x.amount*p.amountToCny;if(!Double.isFinite(amount)||(volume==0&&amount!=0)||(volume>0&&amount==0)){out.reasons[i]="amount-volume-inconsistent";if(!cumulative)tainted=true;continue;}}else if(volume>0){double price=x.close;if(p.mode.equals("hlc3-approx")){if(!Double.isFinite(x.high)||!Double.isFinite(x.low)||x.low<=0||x.high<x.low||x.close<x.low||x.close>x.high){out.reasons[i]="missing-or-invalid-hlc3";tainted=true;continue;}price=x.high/3+x.low/3+x.close/3;}if(!Double.isFinite(price)||price<=0){out.reasons[i]="missing-or-invalid-price";tainted=true;continue;}amount=price*volume;if(!Double.isFinite(amount)){out.reasons[i]="quantity-overflow";tainted=true;continue;}}
 if(cumulative){if((lastV>=0&&volume<lastV)||(lastA>=0&&amount<lastA)){out.reasons[i]="cumulative-decrease";tainted=true;continue;}lastV=volume;lastA=amount;sumV=volume;sumA=amount;}else{sumV+=volume;sumA+=amount;if(!Double.isFinite(sumV)||!Double.isFinite(sumA)){out.reasons[i]="cumulative-overflow";tainted=true;continue;}}if(sumV<=0){out.reasons[i]="zero-total-volume";continue;}double value=sumA/sumV;if(!Double.isFinite(value)||value<=0){out.reasons[i]="invalid-ratio";if(!cumulative)tainted=true;continue;}out.values[i]=value;out.reasons[i]=volume==0?"known-zero-volume":actual?"actual-amount-ratio":"price-volume-approximation";}
 return out;}
 public static String explain(Series s,int i){if(i<0||i>=s.values.length)return "时点不存在";return s.label+"\n"+s.coverage+"\n"+s.explanation+"\n当前状态："+s.reasons[i]+"\n数值："+(Double.isFinite(s.values[i])?String.format(Locale.ROOT,"%.4f",s.values[i]):"未知")+(s.provisional[i]?"\n未闭合时段，数值可随源记录更新":"")+"\n价格相对该线仅为描述，不构成买卖信号或验证完成。";}
}
